  "Deixa-te envolver pelo romantismo europeu. Este vestido de inspiração francesa combina o icónico e intemporal padrão de bolinhas (polka dot) com uma silhueta fluida e charmosa, sendo a peça ideal para quem procura um look feminino, leve e cheio de personalidade para qualquer ocasião especial.": {
    "pt": "Deixe-se envolver pelo romantismo europeu. Este vestido de inspiração francesa combina a icônica e atemporal estampa de bolinhas (polka dot) com uma silhueta fluida e charmosa, tornando-o a peça ideal para quem busca um visual feminino, leve e cheio de personalidade para qualquer ocasião especial.",
    "en": "Let yourself be enveloped by European romanticism. This French-inspired dress combines the iconic and timeless polka dot print with a fluid and charming silhouette, making it the ideal piece for those looking for a feminine, light and personality-filled look for any special occasion.",
    "es": "Let yourself be enveloped by European romanticism. This French-inspired dress combines the iconic and timeless polka dot print with a fluid and charming silhouette, making it the ideal piece for those looking for a feminine, light and personality-filled look for any special occasion.",
    "fr": "Let yourself be enveloped by European romanticism. This French-inspired dress combines the iconic and timeless polka dot print with a fluid and charming silhouette, making it the ideal piece for those looking for a feminine, light and personality-filled look for any special occasion.",
    "de": "Let yourself be enveloped by European romanticism. This French-inspired dress combines the iconic and timeless polka dot print with a fluid and charming silhouette, making it the ideal piece for those looking for a feminine, light and personality-filled look for any special occasion.",
    "it": "Let yourself be enveloped by European romanticism. This French-inspired dress combines the iconic and timeless polka dot print with a fluid and charming silhouette, making it the ideal piece for those looking for a feminine, light and personality-filled look for any special occasion."
  },
  "Impactante, magnético e sofisticado. Este vestido curto é a definição perfeita do estilo \"Sexy Lady\", apresentando um decote halter cruzado no peito que valoriza os ombros e culmina nuns detalhes plissados e drapeados que esculpem o corpo de forma sublime.": {
    "pt": "Impactante, magnético e sofisticado. Este vestido curto é a definição perfeita do estilo \"Sexy Lady\", apresentando um decote halter cruzado no peito que valoriza os ombros e culmina nuns detalhes plissados e drapeados que esculpem o corpo de forma sublime.",
    "en": "Impactful, magnetic and sophisticated. This short dress is the perfect definition of the \"Sexy Lady\" style, featuring a halter neckline crossed across the chest that emphasizes the shoulders and culminates in pleated and draped details that sculpt the body in a sublime way.",
    "es": "Impactful, magnetic and sophisticated. This short dress is the perfect definition of the \"Sexy Lady\" style, featuring a halter neckline crossed across the chest that emphasizes the shoulders and culminates in pleated and draped details that sculpt the body in a sublime way.",
    "fr": "Impactful, magnetic and sophisticated. This short dress is the perfect definition of the \"Sexy Lady\" style, featuring a halter neckline crossed across the chest that emphasizes the shoulders and culminates in pleated and draped details that sculpt the body in a sublime way.",
    "de": "Impactful, magnetic and sophisticated. This short dress is the perfect definition of the \"Sexy Lady\" style, featuring a halter neckline crossed across the chest that emphasizes the shoulders and culminates in pleated and draped details that sculpt the body in a sublime way.",
    "it": "Impactful, magnetic and sophisticated. This short dress is the perfect definition of the \"Sexy Lady\" style, featuring a halter neckline crossed across the chest that emphasizes the shoulders and culminates in pleated and draped details that sculpt the body in a sublime way."
  },
