  "O grande destaque desta peça reside no seu deslumbrante decote assimétrico (asymmetrical neck), complementado por um trabalho minucioso de pregas e painéis sobrepostos (splicing) que enriquecem o design. Com mangas compridas e um caimento fluido, o seu tecido de poliéster de alta qualidade garante conforto duradouro e uma silhueta elegantemente alongada.": {
    "pt": "O grande destaque desta peça reside no seu deslumbrante decote assimétrico (asymmetrical neck), complementado por um trabalho minucioso de pregas e painéis sobrepostos (splicing) que enriquecem o design. Com mangas compridas e um caimento fluido, o seu tecido de poliéster de alta qualidade garante conforto duradouro e uma silhueta elegantemente alongada.",
    "en": "The highlight of this piece lies in its stunning asymmetrical neck, complemented by a detailed work of pleats and overlapping panels (splicing) that enrich the design. With long sleeves and a fluid fit, its high-quality polyester fabric guarantees long-lasting comfort and an elegantly elongated silhouette.",
    "es": "The highlight of this piece lies in its stunning asymmetrical neck, complemented by a detailed work of pleats and overlapping panels (splicing) that enrich the design. With long sleeves and a fluid fit, its high-quality polyester fabric guarantees long-lasting comfort and an elegantly elongated silhouette.",
    "fr": "The highlight of this piece lies in its stunning asymmetrical neck, complemented by a detailed work of pleats and overlapping panels (splicing) that enrich the design. With long sleeves and a fluid fit, its high-quality polyester fabric guarantees long-lasting comfort and an elegantly elongated silhouette.",
    "de": "The highlight of this piece lies in its stunning asymmetrical neck, complemented by a detailed work of pleats and overlapping panels (splicing) that enrich the design. With long sleeves and a fluid fit, its high-quality polyester fabric guarantees long-lasting comfort and an elegantly elongated silhouette.",
    "it": "The highlight of this piece lies in its stunning asymmetrical neck, complemented by a detailed work of pleats and overlapping panels (splicing) that enrich the design. With long sleeves and a fluid fit, its high-quality polyester fabric guarantees long-lasting comfort and an elegantly elongated silhouette."
  },
