  "Uma fusão perfeita entre a alta joalharia e a relojoaria moderna. Este relógio de luxo da marca CUSSI destaca-se pelo seu design artístico único, apresentando um mostrador minimalista dividido em dois tons e uma bracelete rígida estilo \"bangle\" com detalhes vazados. É o acessório ideal para mulheres que procuram uma peça statement discreta, elegante e cheia de personalidade.": {
    "pt": "Uma fusão perfeita entre a alta joalharia e a relojoaria moderna. Este relógio de luxo da marca CUSSI destaca-se pelo seu design artístico único, apresentando um mostrador minimalista dividido em dois tons e uma bracelete rígida estilo \"bangle\" com detalhes vazados. É o acessório ideal para mulheres que procuram uma peça statement discreta, elegante e cheia de personalidade.",
    "en": "A perfect fusion between high jewelry and modern watchmaking. This luxury watch from the CUSSI brand stands out for its unique artistic design, featuring a minimalist dial divided into two tones and a rigid \"bangle\" style bracelet with openwork details. It is the ideal accessory for women looking for a discreet, elegant and personality-filled statement piece.",
    "es": "A perfect fusion between high jewelry and modern watchmaking. This luxury watch from the CUSSI brand stands out for its unique artistic design, featuring a minimalist dial divided into two tones and a rigid \"bangle\" style bracelet with openwork details. It is the ideal accessory for women looking for a discreet, elegant and personality-filled statement piece.",
    "fr": "A perfect fusion between high jewelry and modern watchmaking. This luxury watch from the CUSSI brand stands out for its unique artistic design, featuring a minimalist dial divided into two tones and a rigid \"bangle\" style bracelet with openwork details. It is the ideal accessory for women looking for a discreet, elegant and personality-filled statement piece.",
    "de": "A perfect fusion between high jewelry and modern watchmaking. This luxury watch from the CUSSI brand stands out for its unique artistic design, featuring a minimalist dial divided into two tones and a rigid \"bangle\" style bracelet with openwork details. It is the ideal accessory for women looking for a discreet, elegant and personality-filled statement piece.",
    "it": "A perfect fusion between high jewelry and modern watchmaking. This luxury watch from the CUSSI brand stands out for its unique artistic design, featuring a minimalist dial divided into two tones and a rigid \"bangle\" style bracelet with openwork details. It is the ideal accessory for women looking for a discreet, elegant and personality-filled statement piece."
  },
