  "Uma afirmação de pura classe e elegância discreta. Este vestido longo apresenta um design minimalista com linhas limpas e um sofisticado detalhe drapeado/amarrado na cintura que esculpe a silhueta de forma intemporal, tornando-o a escolha perfeita para eventos formais, jantares de gala ou ocasiões especiais.": {
    "pt": "Uma afirmação de pura classe e elegância discreta. Este vestido longo apresenta um design minimalista com linhas limpas e um sofisticado detalhe drapeado/amarrado na cintura que esculpe a silhueta de forma intemporal, tornando-o a escolha perfeita para eventos formais, jantares de gala ou ocasiões especiais.",
    "en": "A statement of pure class and discreet elegance. This long dress features a minimalist design with clean lines and a sophisticated draped/tied detail at the waist that sculpts the silhouette in a timeless way, making it the perfect choice for formal events, gala dinners or special occasions.",
    "es": "A statement of pure class and discreet elegance. This long dress features a minimalist design with clean lines and a sophisticated draped/tied detail at the waist that sculpts the silhouette in a timeless way, making it the perfect choice for formal events, gala dinners or special occasions.",
    "fr": "A statement of pure class and discreet elegance. This long dress features a minimalist design with clean lines and a sophisticated draped/tied detail at the waist that sculpts the silhouette in a timeless way, making it the perfect choice for formal events, gala dinners or special occasions.",
    "de": "A statement of pure class and discreet elegance. This long dress features a minimalist design with clean lines and a sophisticated draped/tied detail at the waist that sculpts the silhouette in a timeless way, making it the perfect choice for formal events, gala dinners or special occasions.",
    "it": "A statement of pure class and discreet elegance. This long dress features a minimalist design with clean lines and a sophisticated draped/tied detail at the waist that sculpts the silhouette in a timeless way, making it the perfect choice for formal events, gala dinners or special occasions."
  },
