    "en": "Perfect for those who love a bold style, these hoops combine perfectly with the \"Fashion OL Style\" concept, transitioning elegantly from the office to an evening event. Its premium plating guarantees a long-lasting silver shine, keeping the piece light and comfortable despite its maxi size.",
    "es": "Perfect for those who love a bold style, these hoops combine perfectly with the \"Fashion OL Style\" concept, transitioning elegantly from the office to an evening event. Its premium plating guarantees a long-lasting silver shine, keeping the piece light and comfortable despite its maxi size.",
