    "en": "Designed to create a graceful movement when walking, the model features a high waist that elongates the silhouette and a flared skirt that flows in a relaxed way. Its short, lightweight sleeves complete the design, ensuring freshness and total comfort throughout the day.",
    "es": "Designed to create a graceful movement when walking, the model features a high waist that elongates the silhouette and a flared skirt that flows in a relaxed way. Its short, lightweight sleeves complete the design, ensuring freshness and total comfort throughout the day.",
