    "de": "Standing out for its classic dial with Roman numerals and minimalist hands, this watch was designed to also function as an elegant metal bracelet (bracelet watch). Its robust steel structure offers excellent durability, sophisticated shine and the comfortable fit you need for everyday life or formal events.",
    "it": "Standing out for its classic dial with Roman numerals and minimalist hands, this watch was designed to also function as an elegant metal bracelet (bracelet watch). Its robust steel structure offers excellent durability, sophisticated shine and the comfortable fit you need for everyday life or formal events."
