  "A personificação do charme descontraído para os dias quentes. Este vestido longo de corte em \"A\" combina uma silhueta fluida com uma estética minimalista, tornando-o a escolha perfeita para passeios à beira-mar, sunsets ou momentos de lazer com total estilo e frescura.": {
    "pt": "A personificação do charme descontraído para os dias quentes. Este vestido longo de corte \"A\" combina uma silhueta fluida com uma estética minimalista, tornando-o a escolha perfeita para passeios à beira-mar, pôr do sol ou momentos de lazer com total estilo e frescor.",
    "en": "The embodiment of relaxed charm for hot days. This A-line long dress combines a fluid silhouette with a minimalist aesthetic, making it the perfect choice for walks by the sea, sunsets or leisure moments in total style and freshness.",
    "es": "The embodiment of relaxed charm for hot days. This A-line long dress combines a fluid silhouette with a minimalist aesthetic, making it the perfect choice for walks by the sea, sunsets or leisure moments in total style and freshness.",
    "fr": "The embodiment of relaxed charm for hot days. This A-line long dress combines a fluid silhouette with a minimalist aesthetic, making it the perfect choice for walks by the sea, sunsets or leisure moments in total style and freshness.",
    "de": "The embodiment of relaxed charm for hot days. This A-line long dress combines a fluid silhouette with a minimalist aesthetic, making it the perfect choice for walks by the sea, sunsets or leisure moments in total style and freshness.",
    "it": "The embodiment of relaxed charm for hot days. This A-line long dress combines a fluid silhouette with a minimalist aesthetic, making it the perfect choice for walks by the sea, sunsets or leisure moments in total style and freshness."
  },
  "Equipado com um movimento de quartzo analógico ultra preciso e fiável, este modelo apresenta um mostrador redondo clássico e minimalista que facilita a leitura das horas. Graças ao seu tamanho versátil e acabamento premium, oferece um ajuste confortável e intemporal para o dia a dia da mulher moderna.": {
    "pt": "Equipado com um movimento de quartzo analógico ultra preciso e fiável, este modelo apresenta um mostrador redondo clássico e minimalista que facilita a leitura das horas. Graças ao seu tamanho versátil e acabamento premium, oferece um ajuste confortável e intemporal para o dia a dia da mulher moderna.",
    "en": "Equipped with an ultra-precise and reliable analogue quartz movement, this model features a classic, minimalist round dial that makes it easy to read the time. Thanks to its versatile size and premium finish, it offers a comfortable, timeless fit for the modern woman's everyday life.",
    "es": "Equipped with an ultra-precise and reliable analogue quartz movement, this model features a classic, minimalist round dial that makes it easy to read the time. Thanks to its versatile size and premium finish, it offers a comfortable, timeless fit for the modern woman's everyday life.",
    "fr": "Equipped with an ultra-precise and reliable analogue quartz movement, this model features a classic, minimalist round dial that makes it easy to read the time. Thanks to its versatile size and premium finish, it offers a comfortable, timeless fit for the modern woman's everyday life.",
    "de": "Equipped with an ultra-precise and reliable analogue quartz movement, this model features a classic, minimalist round dial that makes it easy to read the time. Thanks to its versatile size and premium finish, it offers a comfortable, timeless fit for the modern woman's everyday life.",
    "it": "Equipped with an ultra-precise and reliable analogue quartz movement, this model features a classic, minimalist round dial that makes it easy to read the time. Thanks to its versatile size and premium finish, it offers a comfortable, timeless fit for the modern woman's everyday life."
  },
  "Graças ao seu corte anatómico e ao fecho de click articulado, estes brincos abraçam o lóbulo da orelha com total leveza e segurança. Disponíveis em vários acabamentos e cores de pedras, são a escolha ideal tanto para usar a solo como para criar composições coloridas e cheias de estilo.": {
    "pt": "Graças ao seu corte anatômico e fecho de clique articulado, esses brincos abraçam o lóbulo da orelha com total leveza e segurança. Disponíveis em vários acabamentos e cores de pedras, elas são a escolha ideal tanto para usar sozinho quanto para criar composições coloridas e estilosas.",
    "en": "Thanks to their anatomical cut and articulated click closure, these earrings hug the earlobe with total lightness and security. Available in various finishes and stone colors, they are the ideal choice both for wearing alone and for creating colorful and stylish compositions.",
    "es": "Thanks to their anatomical cut and articulated click closure, these earrings hug the earlobe with total lightness and security. Available in various finishes and stone colors, they are the ideal choice both for wearing alone and for creating colorful and stylish compositions.",
    "fr": "Thanks to their anatomical cut and articulated click closure, these earrings hug the earlobe with total lightness and security. Available in various finishes and stone colors, they are the ideal choice both for wearing alone and for creating colorful and stylish compositions.",
    "de": "Thanks to their anatomical cut and articulated click closure, these earrings hug the earlobe with total lightness and security. Available in various finishes and stone colors, they are the ideal choice both for wearing alone and for creating colorful and stylish compositions.",
    "it": "Thanks to their anatomical cut and articulated click closure, these earrings hug the earlobe with total lightness and security. Available in various finishes and stone colors, they are the ideal choice both for wearing alone and for creating colorful and stylish compositions."
  },
