const isEnPath = window.location.pathname === '/en' || window.location.pathname.startsWith('/en/');
const SUPPORTED_LANGS = {
  pt: { name: 'Português', flag: 'https://flagcdn.com/w20/pt.png', code: 'PT' },
  en: { name: 'English', flag: 'https://flagcdn.com/w20/gb.png', code: 'EN' },
  es: { name: 'Español', flag: 'https://flagcdn.com/w20/es.png', code: 'ES' },
  fr: { name: 'Français', flag: 'https://flagcdn.com/w20/fr.png', code: 'FR' },
  de: { name: 'Deutsch', flag: 'https://flagcdn.com/w20/de.png', code: 'DE' },
  it: { name: 'Italiano', flag: 'https://flagcdn.com/w20/it.png', code: 'IT' }
};

let savedLang = localStorage.getItem('site_lang') || 'pt';
let currentLang = isEnPath ? 'en' : (SUPPORTED_LANGS[savedLang] && savedLang !== 'en' ? savedLang : 'pt');
window.currentLang = currentLang;

// Automatic translator helper for new products added to the store on the fly
async function autoTranslateText(text, targetLang) {
  if (!text || !targetLang || targetLang === 'pt') return text;
  const clean = text.trim();
  if (!clean) return text;
  const cacheKey = `lb_auto_${targetLang}_${clean}`;
  try {
    const cached = localStorage.getItem(cacheKey);
    if (cached) return cached;
  } catch (e) {}

  try {
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=pt&tl=${encodeURIComponent(targetLang)}&dt=t&q=${encodeURIComponent(clean)}`;
    const res = await fetch(url);
    if (!res.ok) return text;
    const data = await res.json();
    if (Array.isArray(data) && Array.isArray(data[0])) {
      const translated = data[0].map(item => item[0]).join('');
      if (translated) {
        try { localStorage.setItem(cacheKey, translated); } catch (e) {}
        return translated;
      }
    }
  } catch (e) {
    // Graceful fallback to original text
  }
  return text;
}

function applyTranslations() {
  // Apply Dynamic Translations (Descriptions, Options, Size Tables) First
  const dynamicEls = [
    ...document.querySelectorAll('.single-option-selector option'),
    ...document.querySelectorAll('.size-guide-modal__body th'),
    document.querySelector('.product-description'),
    document.querySelector('.product-description-card__content > table'),
    ...document.querySelectorAll('.cart-drawer-item__variant'),
    ...document.querySelectorAll('.cart-rec-item__option-select option')
  ].filter(Boolean);

  dynamicEls.forEach(el => {
    if (el.tagName === 'OPTION') {
      const canonicalKey = el.value || el.getAttribute('data-original-text') || el.textContent.trim();
      if (!el.hasAttribute('data-original-text')) {
        el.setAttribute('data-original-text', canonicalKey);
      }
      const rawKey = el.getAttribute('data-original-text');
      const entry = DYNAMIC_TRANSLATIONS[rawKey] || DYNAMIC_TRANSLATIONS[el.value];
      if (entry && typeof entry === 'object') {
        const translatedVal = entry[currentLang] || entry['en'] || entry['pt'];
        if (translatedVal) {
          el.textContent = translatedVal;
        }
      } else {
        el.textContent = rawKey;
      }
      return;
    }

    if (!el.hasAttribute('data-original-html')) {
      el.setAttribute('data-original-html', el.innerHTML);
    }

    // Reset to original HTML before applying new translations
    el.innerHTML = el.getAttribute('data-original-html');

    // Create a TreeWalker to only visit text nodes
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null, false);
    const textNodes = [];
    let node;
    while (node = walker.nextNode()) {
      if (node.nodeValue.trim() !== '') {
        textNodes.push(node);
      }
    }

    const sortedKeys = Object.keys(DYNAMIC_TRANSLATIONS).sort((a, b) => b.length - a.length);

    textNodes.forEach(textNode => {
      let text = textNode.nodeValue;
      let changed = false;

      sortedKeys.forEach(originalKey => {
        const entry = DYNAMIC_TRANSLATIONS[originalKey];
        const translatedVal = (typeof entry === 'object' && entry !== null)
          ? (entry[currentLang] || entry['en'] || entry['pt'])
          : entry;

        if (translatedVal && translatedVal !== originalKey) {
          if (text.includes(originalKey)) {
            text = text.split(originalKey).join(translatedVal);
            changed = true;
          }
        }
      });

      if (changed) {
        textNode.nodeValue = text;
      }
    });
  });

  // Then apply Static Translations
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (TRANSLATIONS[key]) {
      const transObj = TRANSLATIONS[key];
      const translatedVal = transObj[currentLang] || transObj['en'] || transObj['pt'];
      if (translatedVal) {
        if (translatedVal.includes('<')) {
          el.innerHTML = translatedVal;
        } else {
          if (el.innerHTML.includes('<svg')) {
            const icon = el.innerHTML.match(/<svg[^>]*>.*?<\/svg>/g);
            el.innerHTML = translatedVal + (icon ? icon.join('') : '');
          } else {
            el.textContent = translatedVal;
          }
        }
      }
    }
  });

  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (TRANSLATIONS[key]) {
      const transObj = TRANSLATIONS[key];
      const translatedVal = transObj[currentLang] || transObj['en'] || transObj['pt'];
      if (translatedVal) el.setAttribute('placeholder', translatedVal);
    }
  });

  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria');
    if (TRANSLATIONS[key]) {
      const transObj = TRANSLATIONS[key];
      const translatedVal = transObj[currentLang] || transObj['en'] || transObj['pt'];
      if (translatedVal) el.setAttribute('aria-label', translatedVal);
    }
  });

  document.documentElement.lang = currentLang;

  // Handle Dynamic Counts
  document.querySelectorAll('[data-i18n-count]').forEach(countEl => {
    const num = countEl.getAttribute('data-i18n-count');
    const key = countEl.getAttribute('data-i18n');
    if (key === 'col_found' && TRANSLATIONS['col_found']) {
      const suffix = TRANSLATIONS['col_found'][currentLang] || TRANSLATIONS['col_found']['en'] || TRANSLATIONS['col_found']['pt'];
      countEl.textContent = num + suffix;
    } else if (key === 'list_view' && TRANSLATIONS['list_view'] && TRANSLATIONS['list_view_prefix']) {
      const prefix = TRANSLATIONS['list_view_prefix'][currentLang] || TRANSLATIONS['list_view_prefix']['en'] || TRANSLATIONS['list_view_prefix']['pt'];
      const suffix = TRANSLATIONS['list_view'][currentLang] || TRANSLATIONS['list_view']['en'] || TRANSLATIONS['list_view']['pt'];
      countEl.textContent = prefix + num + suffix;
    }
  });

  // Apply Product Data Translations (Titles and Story Descriptions across all 6 languages)
  const lang = currentLang || 'pt';

  const resolveHandle = (el) => {
    let h = el.getAttribute('data-product-handle');
    if (h) return h;
    const parentWithHandle = el.closest('[data-product-handle]');
    if (parentWithHandle) return parentWithHandle.getAttribute('data-product-handle');
    const href = el.getAttribute('href') || el.closest('a')?.getAttribute('href');
    if (href) {
      const m = href.match(/\/products\/([a-zA-Z0-9_\-]+)/);
      if (m) return m[1];
    }
    const pageMatch = window.location.pathname.match(/\/products\/([a-zA-Z0-9_\-]+)/);
    if (pageMatch) return pageMatch[1];
    return null;
  };

  // 1. Product Titles (Product page, collection, cards, cart drawer, related)
  document.querySelectorAll('[data-product-title], .product-title, .product-card__info h3, .product-card__info h4, .cart-drawer-item__title, .cart-rec-item__title').forEach(el => {
    const handle = resolveHandle(el);
    if (!el.hasAttribute('data-original-text')) {
      el.setAttribute('data-original-text', el.textContent.trim());
    }
    const original = el.getAttribute('data-original-text');
    if (!original) return;

    if (lang === 'pt') {
      const ptText = (typeof PRODUCT_DATA_TRANSLATIONS !== 'undefined' && handle && PRODUCT_DATA_TRANSLATIONS[handle]?.title?.pt) || original;
      el.textContent = ptText;
      if (el.hasAttribute('title')) el.setAttribute('title', ptText);
      return;
    }

    if (typeof PRODUCT_DATA_TRANSLATIONS !== 'undefined' && handle && PRODUCT_DATA_TRANSLATIONS[handle]?.title) {
      const translated = PRODUCT_DATA_TRANSLATIONS[handle].title[lang] || PRODUCT_DATA_TRANSLATIONS[handle].title['en'] || original;
      el.textContent = translated;
      if (el.hasAttribute('title')) el.setAttribute('title', translated);
    } else {
      // Automatic fallback for newly added products!
      autoTranslateText(original, lang).then(translated => {
        if (translated && (currentLang || 'pt') === lang) {
          el.textContent = translated;
          if (el.hasAttribute('title')) el.setAttribute('title', translated);
        }
      });
    }
  });

  // 2. Product Story Paragraphs (Destaque, Detalhe) & Product Descriptions
  document.querySelectorAll('[data-product-story], [data-product-description]').forEach(el => {
    const handle = resolveHandle(el);
    if (!el.hasAttribute('data-original-text')) {
      el.setAttribute('data-original-text', el.textContent.trim());
    }
    const original = el.getAttribute('data-original-text');
    if (!original) return;

    const storyType = el.getAttribute('data-product-story'); // 'top' or 'bottom'

    if (lang === 'pt') {
      const ptText = (typeof PRODUCT_DATA_TRANSLATIONS !== 'undefined' && handle && storyType && PRODUCT_DATA_TRANSLATIONS[handle]?.[storyType]?.pt) || original;
      el.textContent = ptText;
      return;
    }

    if (typeof PRODUCT_DATA_TRANSLATIONS !== 'undefined' && handle && storyType && PRODUCT_DATA_TRANSLATIONS[handle]?.[storyType]) {
      const translated = PRODUCT_DATA_TRANSLATIONS[handle][storyType][lang] || PRODUCT_DATA_TRANSLATIONS[handle][storyType]['en'] || original;
      el.textContent = translated;
    } else {
      // Automatic fallback for newly added products!
      autoTranslateText(original, lang).then(translated => {
        if (translated && (currentLang || 'pt') === lang) {
          el.textContent = translated;
        }
      });
    }
  });

  // 3. Document Title on Product Page
  const pageContainer = document.querySelector('.product-page');
  if (pageContainer) {
    const pageHandle = resolveHandle(pageContainer);
    if (pageHandle && typeof PRODUCT_DATA_TRANSLATIONS !== 'undefined' && PRODUCT_DATA_TRANSLATIONS[pageHandle]?.title) {
      const t = PRODUCT_DATA_TRANSLATIONS[pageHandle].title[lang] || PRODUCT_DATA_TRANSLATIONS[pageHandle].title['pt'];
      if (t) {
        document.title = 'Le Bordeu';
      }
    }
  }
}

function selectLanguage(targetLang) {
  if (!SUPPORTED_LANGS[targetLang]) return;
  localStorage.setItem('site_lang', targetLang);

  currentLang = targetLang;
  window.currentLang = targetLang;
  updateLanguageUI(targetLang);
  applyTranslations();
}

function updateLanguageUI(lang) {
  const conf = SUPPORTED_LANGS[lang] || SUPPORTED_LANGS.pt;
  
  const flagEl = document.querySelector('.lang-current-flag');
  const codeEl = document.querySelector('.lang-current-code');
  if (flagEl) flagEl.innerHTML = `<img src="${conf.flag}" width="16" height="12" alt="${conf.code}">`;
  if (codeEl) codeEl.textContent = conf.code;

  document.querySelectorAll('.lang-dropdown-item').forEach(item => {
    if (item.getAttribute('data-lang') === lang) {
      item.classList.add('is-active');
    } else {
      item.classList.remove('is-active');
    }
  });

  const container = document.getElementById('langDropdownContainer');
  if (container) {
    container.classList.remove('is-open');
    const btn = document.getElementById('langDropdownBtn');
    if (btn) btn.setAttribute('aria-expanded', 'false');
  }
}

function initLanguageDropdown() {
  const isEn = window.location.pathname === '/en' || window.location.pathname.startsWith('/en/');
  let saved = localStorage.getItem('site_lang');
  
  if (saved && SUPPORTED_LANGS[saved]) {
    currentLang = saved;
  } else if (isEn) {
    currentLang = 'en';
  } else {
    currentLang = 'pt';
  }
  window.currentLang = currentLang;

  updateLanguageUI(currentLang);

  const container = document.getElementById('langDropdownContainer');
  const btn = document.getElementById('langDropdownBtn');
  
  if (btn && container) {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const isOpen = container.classList.toggle('is-open');
      btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });

    document.querySelectorAll('.lang-option-btn').forEach(optBtn => {
      optBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const lang = optBtn.getAttribute('data-lang');
        selectLanguage(lang);
      });
    });

    document.addEventListener('click', (e) => {
      if (!container.contains(e.target)) {
        container.classList.remove('is-open');
        btn.setAttribute('aria-expanded', 'false');
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && container.classList.contains('is-open')) {
        container.classList.remove('is-open');
        btn.setAttribute('aria-expanded', 'false');
      }
    });
  }
}

document.addEventListener('DOMContentLoaded', () => {
  initLanguageDropdown();
  applyTranslations();
});
